from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
# Try Databricks REST API for synced tables (the replacement for online tables)
apis_to_try = [
    ('GET', '/api/2.0/preview/capi/serving-endpoints'),
    ('GET', '/api/2.0/preview/online-tables'),
    ('POST', '/api/2.0/preview/online-tables'),
    ('POST', '/api/2.0/lakebase/databases'),
]
for method, path in apis_to_try:
    try:
        if method == 'GET':
            r = w.api_client.do(method, path)
            print(f'{path}: {str(r)[:80]}')
        else:
            print(f'{path}: (POST method, skipping test)')
    except Exception as e:
        print(f'{path}: {type(e).__name__}: {str(e)[:100]}')
" 2>&1

